using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind = {personInfo.Kind}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) Probe without throwing using TryGetTypeInfo
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {found!.Type.Name}");
}

// Now probe for a type whose metadata is NOT available.
// Use options with a resolver that only handles Person.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new PersonOnlyResolver())
};

bool hasOrder = limited.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? orderInfo);
Console.WriteLine($"\nTryGetTypeInfo(Order) on limited resolver: {hasOrder} (info is null: {orderInfo is null})");

// Records used in the demo
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// A resolver that only provides metadata for Person
file class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null; // signal "not available"
    }
}

