using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    WriteIndented = true
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");

// Prove it works by round-tripping
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo returns false if unavailable
//    Use an empty resolver so nothing is resolved
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

bool found = restrictedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probeResult);
Console.WriteLine();
Console.WriteLine($"TryGetTypeInfo with empty resolver => found: {found}, result: {probeResult?.Type.Name ?? "(null)"}");

// Now try with the real resolver — should succeed
bool found2 = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probeResult2);
Console.WriteLine($"TryGetTypeInfo with real resolver  => found: {found2}, result: {probeResult2?.Type.Name ?? "(null)"}");

// --- Types ---

public record Person(string Name, int Age);

// A resolver that intentionally resolves nothing
file class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

